def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N)]
    dp[0][0][0] = grid[0][0]

    for i in range(N):
        for j in range(N):
            for k in range(min(i + j, N - 1) + 1):
                l = i + j - k
                if i > 0 and k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1])
                if i > 0 and l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k])
                if j > 0 and k > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1])
                if j > 0 and l > 0:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k])
                if dp[i][j][k] == -float('inf'):
                    continue
                if i == k and j == l:
                    dp[i][j][k] += grid[i][j]
                else:
                    dp[i][j][k] += grid[i][j] + grid[k][l]

    return max(dp[N-1][N-1])

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # DP table to store the maximum value collected by two paths
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N * 2)]

    # Starting point
    dp[0][0][0] = grid[0][0]

    # Directions for moving down or right
    directions = [(1, 0), (0, 1)]

    # Fill the DP table
    for total_steps in range(1, N * 2 - 1):
        for i in range(max(0, total_steps - (N - 1)), min(N, total_steps + 1)):
            j1, j2 = total_steps - i, i
            for di1, dj1 in directions:
                for di2, dj2 in directions:
                    ni1, nj1 = i + di1, j1 + dj1
                    ni2, nj2 = j2 + di2, j2 + dj2
                    if ni1 < N and nj1 < N and ni2 < N and nj2 < N:
                        new_value = grid[ni1][nj1] + (grid[ni2][nj2] if (ni1, nj1) != (ni2, nj2) else 0)
                        dp[total_steps][ni1][nj1] = max(dp[total_steps][ni1][nj1], dp[total_steps - 1][i][j1] + new_value)

    # The answer is the maximum value collected by both paths reaching the bottom-right corner
    return max(max(row) for row in dp[N * 2 - 2])

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    dp = [[[-1] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)]
    dp[1][1][1] = grid[0][0]

    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                l = i + j - k
                if l < 1 or l > N:
                    continue
                if dp[i][j][k] == -1:
                    continue
                max_val = dp[i][j][k]
                if i + 1 <= N:
                    max_val = max(max_val, dp[i + 1][j][k])
                if j + 1 <= N:
                    max_val = max(max_val, dp[i][j + 1][k])
                if k + 1 <= N:
                    max_val = max(max_val, dp[i][j][k + 1])
                if l + 1 <= N:
                    max_val = max(max_val, dp[i][j][k])

                w1 = grid[i-1][j-1]
                if i != k:
                    w1 += grid[k-1][l-1]

                if i + 1 <= N:
                    dp[i + 1][j][k] = max(dp[i + 1][j][k], max_val + w1)
                if j + 1 <= N:
                    dp[i][j + 1][k] = max(dp[i][j + 1][k], max_val + w1)
                if k + 1 <= N:
                    dp[i][j][k + 1] = max(dp[i][j][k + 1], max_val + w1)
                if l + 1 <= N:
                    dp[i][j][k] = max(dp[i][j][k], max_val + w1)

    return dp[N][N][N]

