                if i > 0 and k > 0 and dp[i-1][j][k-1] != -1:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + grid[i][k])
                if i > 0 and l > 0 and dp[i-1][j][k] != -1:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + grid[i][l])
                if j > 0 and k > 0 and dp[i][j-1][k-1] != -1:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + grid[k][j])
                if j > 0 and l > 0 and dp[i][j-1][k] != -1:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + grid[l][j])
                if dp[i][j][k] != -1 and grid[i][j] == grid[k][l] and i != k:
                    dp[i][j][k] -= grid[i][j]

    max_sum = 0
    for i in range(N):
        for j in range(N):
            if dp[N-1][i][j] != -1:
                max_sum = max(max_sum, dp[N-1][i][j])
