def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Create a dictionary to store the grid values
    grid = defaultdict(int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[(x - 1, y - 1)] = value

    # Initialize the dp table
    dp = [[[-float('inf')] * (N + 1) for _ in range(N + 1)] for _ in range(N + 1)]
    dp[1][1][1] = grid[(0, 0)]

    # Fill the dp table
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            for k in range(1, N + 1):
                l = i + j - k
                if 1 <= l <= N and (i, j) != (k, l):
                    val1 = grid[(i - 1, j - 1)]
                    val2 = grid[(k - 1, l - 1)]
                    dp[i][j][k] = max(
                        dp[i][j][k],
                        dp[i - 1][j][k] + val1 + val2,
                        dp[i][j - 1][k] + val1 + val2,
                        dp[i][j][k - 1] + val1 + val2,
                        dp[i - 1][j][k - 1] + val1 + val2
                    )

    return max(0, dp[N][N][N])

def find_number_combinations():
    def is_unique(n1, n2, n3):
        digits = str(n1) + str(n2) + str(n3)
        return len(set(digits)) == len(digits)

    combinations = []
    for n1 in range(123, 334):  # 334 is the max number that can be tripled to 999
        n2 = n1 * 2
        n3 = n1 * 3
        digits = str(n1) + str(n2) + str(n3)
        if len(digits) == 9 and is_unique(n1, n2, n3):
