    def generate_numbers():
        from itertools import permutations
        for p in permutations(range(1, 10), 3):
            yield int(''.join(map(str, p)))

    combinations = []
    for num1 in generate_numbers():
        num2 = num1 * 2
        num3 = num1 * 3
        digits = set(int(d) for d in str(num1) + str(num2) + str(num3))
        if len(digits) == 9 and 1 <= num2 < 1000 and 1 <= num3 < 1000:
            combinations.append((num1, num2, num3))

    return sorted(combinations)

