def max_product(num_str: str, N: int, K: int) -> int:
    def product_of_splits(splits):
        product = 1
        for split in splits:
            product *= int(split)
        return product

    def dfs(start, k, current_splits):
        if k == 0:
            current_splits.append(num_str[start:])
            result = product_of_splits(current_splits)
            current_splits.pop()
            return result
        max_prod = 0
        for i in range(start + 1, N - k + 2):
            current_splits.append(num_str[start:i])
            max_prod = max(max_prod, dfs(i, k - 1, current_splits))
            current_splits.pop()
        return max_prod

    return dfs(0, K, [])

