def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i, char in enumerate(isbn.replace('-', '')):
            if char == 'X':
                value = 10
            else:
                value = int(char)
            total += value * (10 - i)
        return total % 11

    original_checksum = isbn[-1]
    cleaned_isbn = isbn[:-1].replace('-', '')
    calculated_checksum = calculate_checksum(cleaned_isbn + 'X' if original_checksum == 'X' else cleaned_isbn + '0')

    if calculated_checksum == 0:
        correct_checksum = '0'
    elif calculated_checksum == 1:
        correct_checksum = 'X'
    else:
        correct_checksum = str(11 - calculated_checksum)

    if correct_checksum == original_checksum:
        return "Right"
    else:
        return f"{cleaned_isbn}-{correct_checksum}"

def verify_isbn(isbn: str) -> str:
    # Remove dashes and convert to list of characters
    chars = isbn.replace('-', '')

    # Calculate the expected checksum
    total = 0
    for i in range(9):
        total += int(chars[i]) * (10 - i)

    # Calculate the checksum digit
    remainder = total % 11
    checksum = 11 - remainder
    if checksum == 10:
        expected_checksum = 'X'
    elif checksum == 11:
        expected_checksum = '0'
    else:
        expected_checksum = str(checksum)

    # Compare the expected checksum with the provided one
    if expected_checksum == chars[9]:
        return "Right"
    else:
        # Return the corrected ISBN
        return isbn[:-1] + expected_checksum

def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> str:
        parts = isbn.split('-')
        digits = parts[0] + parts[1] + parts[2] + parts[3][:-1]
        total = sum((i + 1) * int(d) for i, d in enumerate(digits))
        checksum = (11 - (total % 11)) % 11
        return 'X' if checksum == 10 else str(checksum)

    correct_checksum = calculate_checksum(isbn)
    provided_checksum = isbn[-1]

    if correct_checksum == provided_checksum:
        return "Right"
    else:
        return isbn[:-1] + correct_checksum

