def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Initialize counts for rows and columns
    row_counts = [0] * (M + 1)
    col_counts = [0] * (N + 1)

    # Count the number of chatting pairs that can be separated by each potential aisle
    for (X1, Y1, X2, Y2) in chatting_pairs:
        if X1 == X2:
            # Vertical aisle can separate them
            if Y1 < Y2:
                col_counts[Y2] += 1
            else:
                col_counts[Y1] += 1
        elif Y1 == Y2:
            # Horizontal aisle can separate them
            if X1 < X2:
                row_counts[X2] += 1
            else:
                row_counts[X1] += 1

    # Sort rows and columns by the number of separations they can achieve, in descending order
    sorted_rows = sorted(range(1, M + 1), key=lambda x: row_counts[x], reverse=True)
    sorted_cols = sorted(range(1, N + 1), key=lambda x: col_counts[x], reverse=True)

    # Select the top K horizontal aisles and top L vertical aisles
    selected_rows = sorted_rows[:K]
    selected_cols = sorted_cols[:L]

    # Convert to space-separated strings
    row_str = ' '.join(map(str, selected_rows))
    col_str = ' '.join(map(str, selected_cols))

    return (row_str, col_str)

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    def count_separated_pairs(horizontal_aisles, vertical_aisles, pair):
        (x1, y1, x2, y2) = pair
        separated_by_horizontal = any(aisle between x1 and x2 for aisle in horizontal_aisles)
        separated_by_vertical = any(aisle between y1 and y2 for aisle in vertical_aisles)
        return separated_by_horizontal or separated_by_vertical

    horizontal_potential = [0] * (M + 1)
    vertical_potential = [0] * (N + 1)

    for pair in chatting_pairs:
        (x1, y1, x2, y2) = pair
        if x1 != x2:
            low, high = sorted([x1, x2])
            for i in range(low, high):
                horizontal_potential[i] += 1
        if y1 != y2:
            low, high = sorted([y1, y2])
            for i in range(low, high):
                vertical_potential[i] += 1

    horizontal_aisles = sorted(range(1, M), key=lambda x: -horizontal_potential[x])[:K]
    vertical_aisles = sorted(range(1, N), key=lambda x: -vertical_potential[x])[:L]

    return (' '.join(map(str, sorted(horizontal_aisles))), ' '.join(map(str, sorted(vertical_aisles))))

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    def count_separated_pairs(h_aisles, v_aisles):
        separated_count = 0
        for (x1, y1, x2, y2) in chatting_pairs:
            if (x1 <= h_aisles < x2 or x2 <= h_aisles < x1) or (y1 <= v_aisles < y2 or y2 <= v_aisles < y1):
                separated_count += 1
        return separated_count

    h_aisles, v_aisles = [], []
    h_effectiveness = [0] * (M - 1)
    v_effectiveness = [0] * (N - 1)

    for (x1, y1, x2, y2) in chatting_pairs:
        if x1 != x2:
            h_effectiveness[min(x1, x2) - 1] += 1
        if y1 != y2:
            v_effectiveness[min(y1, y2) - 1] += 1

    for _ in range(K):
        h_max_index = max(range(M - 1), key=lambda i: h_effectiveness[i])
        h_aisles.append(h_max_index + 1)
        h_effectiveness[h_max_index] = 0

    for _ in range(L):
        v_max_index = max(range(N - 1), key=lambda i: v_effectiveness[i])
        v_aisles.append(v_max_index + 1)
        v_effectiveness[v_max_index] = 0

    h_aisles.sort()
    v_aisles.sort()

    return ' '.join(map(str, h_aisles)), ' '.join(map(str, v_aisles))

def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    row_counts = [0] * (M + 1)
    col_counts = [0] * (N + 1)

    for (xi, yi, pi, qi) in chatting_pairs:
        if xi == pi:  # same row
            if yi < qi:
                col_counts[yi] += 1
                col_counts[qi] += 1
            else:
                col_counts[qi] += 1
                col_counts[yi] += 1
        elif yi == qi:  # same column
            if xi < pi:
                row_counts[xi] += 1
                row_counts[pi] += 1
            else:
                row_counts[pi] += 1
                row_counts[xi] += 1

