def max_energy(beads):
    n = len(beads)
    beads = beads + beads[:-1]  # Duplicate the list to handle circular nature
    dp = [[0] * (2 * n) for _ in range(2 * n)]

    for length in range(2, n + 1):
        for i in range(n):
            j = i + length - 1
            for k in range(i + 1, j + 1):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j + 1])

    return max(dp[i][i + n - 1] for i in range(n))

def max_energy(beads):
