    # Extend the beads array to handle circular nature
    beads = beads + beads

    # DP table to store maximum energy for merging beads[i:j]
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the DP table
    for length in range(3, n + 2):  # length of the segment
        for i in range(n):
            j = i + length - 1
            if j >= n + 1:
                continue
            for k in range(i + 1, j):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j])

    # The result is the maximum energy for merging any segment of length n
    return max(dp[i][i + n] for i in range(n))

