                if (statement == f"{scenario} is guilty." and scenario != participant) or \
                   (statement == f"{scenario} is not guilty." and scenario == participant):
                    break
            else:
                # Truth-teller's statement should be true in this scenario
                if (statement == f"{scenario} is guilty." and scenario == participant) or \
