def vigenere_decrypt(key: str, ciphertext: str) -> str:
    def shift_char(c: str, k: str) -> str:
        return chr((ord(c) - ord(k) + 26) % 26 + ord('a')) if c.islower() else chr((ord(c) - ord(k) + 26) % 26 + ord('A'))

    key = key.lower()
    key_length = len(key)
    decrypted_text = []

    for i, char in enumerate(ciphertext):
        if char.isalpha():
            decrypted_char = shift_char(char, key[i % key_length])
            decrypted_text.append(decrypted_char)
        else:
            decrypted_text.append(char)

    return ''.join(decrypted_text).lower()

def mod_inverse(a, b):
    def extended_gcd(aa, bb):
        if aa == 0:
            return bb, 0, 1
        gcd, x1, y1 = extended_gcd(bb % aa, aa)
        x = y1 - (bb // aa) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

