def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0

    left_increasing = [1] * n
    right_decreasing = [1] * n

    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left_increasing[i] = left_increasing[i - 1] + 1

    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right_decreasing[i] = right_decreasing[i + 1] + 1

    max_students_in_choir = 0
    for i in range(n):
        max_students_in_choir = max(max_students_in_choir, left_increasing[i] + right_decreasing[i] - 1)

    return n - max_students_in_choir

